#!/bin/bash
# Analyze the debug log to show session changes and token counts

awk '
/^=== / {
    timestamp = $2 " " $3
}
/"session_id":/ {
    gsub(/[",]/, "", $2)
    session = substr($2, 1, 8)
}
/"total_input_tokens":/ {
    gsub(/[",]/, "", $2)
    input_tokens = $2
}
/"total_output_tokens":/ {
    gsub(/[",]/, "", $2)
    output_tokens = $2
    total = input_tokens + output_tokens
    printf "%s | sid:%s | in:%5d out:%5d total:%5d\n", timestamp, session, input_tokens, output_tokens, total
}
' /tmp/statusline_debug.log | tail -30

